const BUSINESSES=[{name:'Brisling & Co.',place:'Storhaug',type:'Et gammelt fabrikklokale. En ny begynnelse.',cost:35000,income:2100},{name:'Nattåpent',place:'Pedersgata',type:'Kaffe, småprat og en litt for travel bakdør.',cost:90000,income:5500},{name:'Sjøsprøyt',place:'Vågen',type:'Fiktiv nattklubb. Utsikt mot båtene.',cost:210000,income:12400},{name:'Siste Skift',place:'Østre bydel',type:'Verkstedet som aldri spør hvor ting kommer fra.',cost:410000,income:24000}];
const EVENTS=[{title:'En telefon fra Bergen',body:'En fiktiv aktør vil samarbeide om vestkysten. Lavere margin eller større rekkevidde?',choices:[{name:'Bygg alliansen',rep:8,heat:-4,cash:-6000},{name:'Vi står på egne bein',rep:3,heat:3,cash:7000}]},{title:'Regn over Vågen',body:'En uke med tomme gater. Folkene dine vil ha fri, men faste utgifter tar ikke ferie.',choices:[{name:'Ta vare på laget',rep:5,heat:-8,cash:-3500},{name:'Hold hjulene i gang',rep:1,heat:5,cash:6000}]},{title:'Et gammelt fabrikklokale',body:'En kontakt tilbyr et lager i et tidligere hermetikkmiljø. Historien sitter i veggene. Husleia også.',choices:[{name:'Bygg lokale bånd',rep:7,heat:-3,cash:-5000},{name:'Selg tipset videre',rep:0,heat:2,cash:8000}]},{title:'Byen begynner å hviske',body:'Ryktene har kommet før deg. Nå må du velge hva navnet ditt skal bety.',choices:[{name:'Respekt varer lengst',rep:9,heat:-5,cash:-8000},{name:'Vekst koster',rep:4,heat:9,cash:14000}]}];
