function fresh(){return {v:1,name:'Skipperen',week:0,cash:25000,rep:0,heat:8,stock:[0,0,0,0],districts:[],businesses:[],cities:[0],managers:0,auto:false,policy:'balanced',goal:'coast',event:null,log:['2026. Du står på kaien i Stavanger. 25 000 kroner. Ingen som skylder deg noe.'],lastIncome:0,ended:false};}
function prices(s,i){const g=GOODS[i],wave=1+Math.sin(s.week*.9+i*2)*.15;return {buy:Math.round(g.buy*wave),sell:Math.round(g.sell*(1+Math.cos(s.week*.7+i)*.18))};}
function rank(s){return s.rep>=165?'Gudfar':s.rep>=120?'Strateg':s.rep>=85?'Bykonge':s.rep>=55?'Bakmann':s.rep>=25?'Operatør':s.rep>=8?'Løpegutt':'Ukjent';}
function income(s){return s.districts.reduce((a,i)=>a+DISTRICTS[i].income,0)+s.businesses.reduce((a,i)=>a+BUSINESSES[i].income,0)+s.cities.reduce((a,i)=>a+CITIES[i].income,0);}
function note(s,t){s.log.unshift(t);s.log=s.log.slice(0,60);}
function act(s,type,arg){if(s.ended)return 'Runden er avsluttet.';if(s.event&&type!=='choice'&&type!=='goal'&&type!=='policy'&&type!=='auto')return 'Ta stilling til hendelsen først.';
let msg='';const i=Number(arg);
if(type==='buy'){if(!GOODS[i]||s.rep<GOODS[i].rep)return 'Bygg mer respekt først.';const p=prices(s,i).buy,capacity=100+s.managers*100-s.stock.reduce((a,b)=>a+b,0),n=Math.min(10,capacity,Math.floor(s.cash/p));if(n<1)return 'For lite penger eller full lagerplass.';s.stock[i]+=n;s.cash-=n*p;msg=`Kjøpte ${n} enheter ${GOODS[i].name.toLowerCase()}.`;}
if(type==='sell'){if(!s.stock[i])return 'Lageret er tomt.';const n=s.stock[i];s.cash+=n*prices(s,i).sell;s.stock[i]=0;s.rep+=Math.max(1,Math.floor(n/10));s.heat=Math.min(100,s.heat+3);msg=`Solgte ${n} enheter ${GOODS[i].name.toLowerCase()}.`;}
if(type==='district'||type==='business'||type==='city'){const list=type==='district'?DISTRICTS:type==='business'?BUSINESSES:CITIES,key=type==='district'?'districts':type==='business'?'businesses':'cities',item=list[i];if(!item||s[key].includes(i))return 'Allerede en del av nettverket.';if(type==='city'&&new Date(Date.UTC(2026,0,1+s.week*7)).getUTCFullYear()<item.year)return 'Denne byen åpner i '+item.year+'.';if(s.cash<item.cost)return 'Du trenger mer kapital.';if(type==='city'&&(s.rep<item.rep||s.managers<s.cities.length))return 'Du trenger mer respekt og én leder per ny by.';s.cash-=item.cost;s[key].push(i);s.rep+=type==='city'?14:5;s.heat=Math.min(100,s.heat+5);msg=`${item.name} er nå del av nettverket.`;}
if(type==='manager'){const cost=15000*(s.managers+1);if(s.cash<cost)return 'Du trenger mer kapital.';s.cash-=cost;s.managers++;s.rep+=2;msg='En ny driftsleder tar seg av det daglige.';}
if(type==='auto'){if(!s.managers)return 'Ansett en driftsleder først.';s.auto=!s.auto;msg=s.auto?'Handelsruten går automatisk hver uke.':'Den automatiske handelsruten er satt på pause.';}
if(type==='policy'){if(!['safe','balanced','growth'].includes(arg))return 'Ukjent strategi.';s.policy=arg;msg='Driftsstrategien er oppdatert.';}
if(type==='goal'){if(!['coast','country','exit'].includes(arg))return 'Ukjent sluttmål.';s.goal=arg;msg='Ambisjonen din er oppdatert.';}
if(type==='choice'){if(!s.event||![0,1].includes(i))return 'Ingen hendelse.';const c=EVENTS[s.event.id].choices[i];if(s.cash+c.cash<0)return 'Du har ikke råd til dette valget.';s.cash+=c.cash;s.rep+=c.rep;s.heat=Math.max(0,Math.min(100,s.heat+c.heat));s.event=null;msg=c.name+'.';}
if(type==='week'||type==='rest'||type==='shift'){s.week++;let gross=income(s),factor=s.policy==='safe'?.8:s.policy==='growth'?1.3:1;let trade=s.auto?Math.round((1500+s.rep*95)*s.managers):0;const costs=s.managers*750+500;let net=Math.round(gross*factor+trade-costs)+(type==='shift'?3500:0);if(type==='shift')s.rep+=1;if(type==='rest'){s.heat=Math.max(0,s.heat-20);net=Math.round(net*.5);}else{s.heat=Math.max(0,Math.min(100,s.heat+(s.policy==='growth'?5:s.policy==='safe'?-6:-2)+(s.auto?2:0)));}s.cash=Math.max(0,s.cash+net);s.lastIncome=net;if(gross||trade)s.rep+=s.policy==='growth'?2:1;if(s.heat>=75){const fine=Math.round(s.cash*.08);s.cash-=fine;s.heat-=25;note(s,`Etterforskning kostet deg ${fine.toLocaleString('nb-NO')} kr. Søkelyset faller.`);}msg=`Uke ${s.week}: ${net>=0?'+':''}${net.toLocaleString('nb-NO')} kr etter drift.`;if(s.week%6===0)s.event={id:(s.week/6-1)%EVENTS.length};if(s.week>=574){s.ended=true;s.event=null;msg='2036 er over. Historien din er skrevet.';}}
if(msg)note(s,msg);if(type==='sell')act(s,'week');return msg;}
function outcome(s){const coast=s.cities.includes(1)&&s.districts.length>=3,country=s.cities.length===5,exit=s.cash>=5000000&&s.heat<=25;return {won:s.goal==='coast'?coast:s.goal==='country'?country:exit,coast,country,exit};}
function addHeat(s,n){s.heat=Math.max(0,Math.min(100,s.heat+n*(n>0?(root.Game.itemModifiers?.(s).heatGain||1):1)));}
